@Composable
internal fun FoniWiseLegacyVisuals(title:String, english:Boolean) {
    legacySpecs(title).forEach { s -> key(title,s.id,english) { LegacyVisual(s,english) } }
}

private fun Element.nodes():List<Element> = listOf(this)+(0 until childNodes.length).flatMap {
    (childNodes.item(it) as? Element)?.nodes() ?: emptyList()
}
private fun Element.byId(id:String)=nodes().firstOrNull{it.getAttribute("id")==id}
private fun Element.byClass(name:String)=nodes().filter{it.getAttribute("class").split(" ").contains(name)}
private fun Element.attr(id:String,k:String,v:String){byId(id)?.setAttribute(k,v)}
private fun Element.txt(id:String,v:String){byId(id)?.textContent=v}
private fun Element.show(id:String,on:Boolean){attr(id,"visibility",if(on) "visible" else "hidden")}
private fun Element.display(id:String,on:Boolean){attr(id,"display",if(on) "inline" else "none")}
private fun Element.clear(){while(hasChildNodes()) removeChild(firstChild)}
private fun Element.rect(x:Float,y:Float,w:Float,h:Float,fill:String) {
    val r=ownerDocument.createElement("rect")
    mapOf("x" to x.toString(),"y" to y.toString(),"width" to w.toString(),"height" to h.toString(),"fill" to fill).forEach{(k,v)->r.setAttribute(k,v)}
    appendChild(r)
}

@Composable
private fun Diagram(xml:String,desc:String,state:Any=0,edit:(Element)->Unit={}) {
    val ctx=LocalContext.current
    val font=remember(ctx){ctx.resources.getFont(R.font.nunito_sans)}
    val root=remember(xml,state){DocumentBuilderFactory.newInstance().apply{isExpandEntityReferences=false}.newDocumentBuilder().parse(xml.byteInputStream(Charsets.UTF_8)).documentElement.apply(edit)}
    val view=remember(root){root.getAttribute("viewBox").trim().split(Regex("[ ,]+")).map{it.toFloat()}}
    Canvas(Modifier.fillMaxWidth().aspectRatio(view[2]/view[3]).semantics{contentDescription=desc}){
        drawIntoCanvas{
            val c=it.nativeCanvas;val save=c.save()
            c.clipRect(0f,0f,size.width,size.height)
            c.scale(size.width/view[2],size.height/view[3]);c.translate(-view[0],-view[1])
            drawFoniWiseStaticSvg(c,root,font);c.restoreToCount(save)
        }
    }
}
@Composable
private fun Choices(label:String,items:List<String>,selected:Int,change:(Int)->Unit){
    Text(label,color=dark,fontWeight=FontWeight.Bold)
    items.forEachIndexed{i,t->FilterChip(selected=i==selected,onClick={change(i)},label={Text(t,color=dark)},colors=FilterChipDefaults.filterChipColors(containerColor=pale,selectedContainerColor=lime),modifier=Modifier.fillMaxWidth().heightIn(min=48.dp))}
}
@Composable
private fun Range(label:String,v:Int,lo:Int,hi:Int,step:Int=1,change:(Int)->Unit){
    Text(label,color=dark,fontWeight=FontWeight.Bold)
    Slider(value=v.toFloat(),onValueChange={change((lo+((it-lo)/step).roundToInt()*step).coerceIn(lo,hi))},valueRange=lo.toFloat()..hi.toFloat(),steps=(hi-lo)/step-1,modifier=Modifier.fillMaxWidth().heightIn(min=48.dp).semantics{contentDescription=label})
}
@Composable
private fun Result(t:String){Surface(color=pale,shape=RoundedCornerShape(8.dp),modifier=Modifier.fillMaxWidth().semantics{liveRegion=LiveRegionMode.Polite}){Text(t,color=dark,modifier=Modifier.padding(12.dp))}}
@Composable
private fun Bar(parts:List<Pair<Float,Color>>,height:Int=22){
    Canvas(Modifier.fillMaxWidth().height(height.dp).background(pale,RoundedCornerShape(5.dp))){
        var x=0f;parts.forEach{(f,c)->val w=f.coerceIn(0f,1f)*size.width;if(w>0)drawRect(c,androidx.compose.ui.geometry.Offset(x,0f),androidx.compose.ui.geometry.Size(w,size.height));x+=w}
    }
}
@Composable
private fun Battery(label:String,reserve:Int,color:Color){
    Column(horizontalAlignment=Alignment.CenterHorizontally){
        Box(Modifier.width(30.dp).height(8.dp).background(green,RoundedCornerShape(3.dp)))
        Surface(shape=RoundedCornerShape(9.dp),border=androidx.compose.foundation.BorderStroke(2.dp,green),color=Color.White,modifier=Modifier.width(86.dp).height(104.dp)){
            Box(Modifier.padding(6.dp)){
                Box(Modifier.align(Alignment.BottomCenter).fillMaxWidth().fillMaxHeight(reserve/100f).background(color,RoundedCornerShape(4.dp)))
                Text("100%",color=dark,fontWeight=FontWeight.Bold,modifier=Modifier.align(Alignment.Center).background(Color.White.copy(alpha=.85f)).padding(4.dp))
            }
        }
        Text(label,color=dark,modifier=Modifier.padding(4.dp))
    }
}
@Composable
private fun LegacyVisual(s:LegacySpec,en:Boolean){
    fun tr(ro:String,eng:String)=if(en)eng else ro
    val n0=when(s.id){1,34->80;8->400;33->4;36->6;else->1}
    val p0=when(s.id){2,7->1;9->2;29->-1;else->0}
    var n by rememberSaveable{mutableIntStateOf(n0)}
    var p by rememberSaveable{mutableIntStateOf(p0)}
    var p2 by rememberSaveable{mutableIntStateOf(0)}
    var a by rememberSaveable{mutableStateOf(s.id==11)}
    var b by rememberSaveable{mutableStateOf(false)}
    val fmt=remember(en){NumberFormat.getNumberInstance(if(en) Locale.US else Locale.forLanguageTag("ro-RO")).apply{maximumFractionDigits=3}}
    val one=remember(en){NumberFormat.getNumberInstance(if(en) Locale.US else Locale.forLanguageTag("ro-RO")).apply{maximumFractionDigits=1;minimumFractionDigits=1}}
    val svg=if(en)s.enSvg else s.roSvg
    val title=tr(s.ro,s.en)
    Surface(color=bg,shape=RoundedCornerShape(12.dp),modifier=Modifier.fillMaxWidth()){
        Column(Modifier.padding(12.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){
            Surface(color=dark,shape=RoundedCornerShape(8.dp),modifier=Modifier.fillMaxWidth()){Text(title,color=Color.White,fontWeight=FontWeight.Bold,modifier=Modifier.padding(12.dp))}
            when(s.id){
                1->{
                    Text(tr("Capacitate inițială: ","Initial capacity: ")+fmt.format(5000)+" mAh",color=dark)
                    Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceEvenly){
                        Battery(tr("Baterie nouă","New battery"),100,green)
                        Battery(tr("Baterie degradată","Aged battery"),n,if(n>=80)green else if(n>=60)Color(0xFFD6A32F) else Color(0xFFC96846))
                    }
                    Range(tr("Sănătatea bazată pe capacitate: ","Capacity-based health: ")+n+"%",n,40,100){n=it}
                    Result(tr("Capacitate rămasă: ","Remaining capacity: ")+fmt.format(50*n)+" mAh\n"+tr("Capacitate pierdută: ","Lost capacity: ")+fmt.format(5000-50*n)+" mAh")
                }
                2->{
                    val cores=listOf(1,2,4,8)[p]
                    Diagram(svg[0],title,cores){r->
                        r.byClass("v02core").forEachIndexed{i,e->e.setAttribute("fill",if(i<cores)"#087C26" else "#C5E9B6")}
                        r.byClass("v02number").forEachIndexed{i,e->e.setAttribute("fill",if(i<cores)"white" else "#064D2B")}
                        r.txt("v02chiplabel",if(en) "$cores "+(if(cores==1)"active core" else "active cores")+" in simulation" else "$cores "+(if(cores==1)"nucleu activ" else "nuclee active")+" în simulare")
                    }
                    Diagram(svg[1],tr("Comparație durate","Duration comparison"))
                    Choices(tr("Număr de nuclee","Number of cores"),listOf("1","2","4","8"),p){p=it}
                    Bar(listOf(.4f to dark,(.6f/cores) to graphic),24)
                    Result(tr("Durata totală: ","Total duration: ")+fmt.format(4+6.0/cores)+" s · "+tr("Timp economisit: ","Time saved: ")+fmt.format((6-6.0/cores)*10)+"%")
                }
                3->{
                    Diagram(svg[0],title,a){it.attr("v03removed","opacity",if(a) "0.12" else "1")}
                    Button(onClick={a=true},modifier=Modifier.fillMaxWidth().heightIn(min=48.dp)){Text(tr("Simulează dezinstalarea","Simulate uninstalling"))}
                    Result(if(a)tr("200 MB eliberați · 300 MB fotografii rămase","200 MB freed · 300 MB photos remain") else tr("Spațiu ocupat în exemplu: 500 MB.","Used space in example: 500 MB."))
                }
                7->{
                    val touch=listOf(60,120,240)[p];val display=listOf(60,90,120)[p2]
                    Diagram(svg[0],title)
                    Choices(tr("Detectarea atingerii","Touch detection"),listOf("60 Hz","120 Hz","240 Hz"),p){p=it}
                    Choices(tr("Afișaj","Display"),listOf("60 Hz","90 Hz","120 Hz"),p2){p2=it}
                    listOf(tr("Detectare","Detection") to touch,tr("Afișaj","Display") to display).forEach{(label,f)->
                        Text(label,color=dark)
                        Row(Modifier.fillMaxWidth().height(22.dp),horizontalArrangement=Arrangement.spacedBy(2.dp)){repeat((f/10.0).roundToInt()){Box(Modifier.weight(1f).fillMaxHeight().background(green))}}
                    }
                    Result(tr("Atingere: ","Touch: ")+one.format(1000.0/touch)+" ms · "+tr("Afișaj: ","Display: ")+one.format(1000.0/display)+" ms")
                }
                8->{
                    Diagram(svg[0],title,n){r->
                        val shade=(400-n)/300f
                        r.attr("v08shade","opacity",(.05f+.45f*shade).toString())
                        r.byClass("v08noise").forEach{it.setAttribute("opacity",(.05f+.65f*shade).toString())}
                        r.byClass("v08ray").forEach{it.setAttribute("opacity",(.25f+.75f*n/400).toString())}
                    }
                    Range(tr("Fotoni colectați în exemplu: ","Photons collected in example: ")+n,n,100,400,25){n=it}
                    Result(n.toString()+tr(" fotoni · Raport semnal-zgomot: "," photons · Signal-to-noise ratio: ")+one.format(sqrt(n.toDouble())))
                }
                9->{
                    val rate=listOf(16000,44100,48000)[p];val mb=rate*2.0*n*60/1e6
                    Diagram(svg[0],title)
                    Choices(tr("Eșantioane pe secundă","Samples per second"),listOf("16 000","44 100","48 000"),p){p=it}
                    Range(tr("Durată (minute): ","Duration (minutes): ")+n,n,1,10){n=it}
                    Result("$n min · "+fmt.format(mb)+" MB")
                    Bar(listOf((mb/57.6).toFloat() to green))
                }
                11->{
                    val names=if(en)listOf("Microphone","Camera","Location") else listOf("Microfon","Cameră","Locație")
                    val status=if(!b)tr("Nicio solicitare de acces","No access request") else if(a)tr("Acces permis în simulare","Access allowed in simulation") else tr("Acces refuzat în simulare","Access denied in simulation")
                    Diagram(svg[0],title,listOf(p,a,b)){r->
                        listOf("mic","cam","loc").forEachIndexed{i,k->r.display("v11"+k,p==i)}
                        r.txt("v11part",names[p]);r.attr("v11shield","fill",if(a)"#087C26" else "#A66A35")
                        r.attr("v11mark","d",if(a)"M145 83 L155 94 177 68" else "M148 70 L172 94 M172 70 L148 94")
                        r.attr("v11link","stroke",if(a&&b)"#087C26" else "#A4B5A0");r.attr("v11link","stroke-dasharray",if(a&&b)"none" else "4 4")
                        r.attr("v11bg","fill",if(a&&b)"#B5F52C" else "#D1E6C5");r.txt("v11status",status)
                    }
                    Choices(tr("Componenta telefonului","Phone component"),names,p){p=it;b=false}
                    Row(Modifier.fillMaxWidth().heightIn(min=48.dp),verticalAlignment=Alignment.CenterVertically){Checkbox(checked=a,onCheckedChange={a=it;b=false});Text(tr("Permisiune acordată","Permission granted"),color=dark)}
                    Button(onClick={b=!b},modifier=Modifier.fillMaxWidth().heightIn(min=48.dp)){Text(if(b)tr("Oprește solicitarea simulată","Stop simulated request")else tr("Simulează o solicitare de acces","Simulate an access request"))}
                    Result(tr("Permisiune: ","Permission: ")+(if(a)tr("acordată","granted")else tr("neacordată","not granted"))+" · "+tr("Acces: ","Access: ")+(if(!b)tr("nu","no")else if(a)tr("da","yes")else tr("refuzat","denied")))
                }
                29->{
                    Diagram(svg[0],title,p){r->r.nodes().filter{it.tagName=="rect"}.drop(1).forEachIndexed{i,e->e.setAttribute("stroke-width",if(i==p)"3" else "1");e.setAttribute("fill",if(i==p)"#B5F52C" else "#E7F8DB")}}
                    Choices(tr("Explorează funcțiile","Explore functions"),if(en)listOf("Charging","File transfer","ADB debugging")else listOf("Încărcare","Transfer fișiere","Depanare ADB"),p){p=it}
                    if(p>=0)Result(if(en)listOf("Power can charge the battery.","File transfer exchanges files with an authorized computer.","ADB permits authorized diagnostic operations.")[p]else listOf("Energia poate încărca bateria.","Transferul de fișiere schimbă fișiere cu un calculator autorizat.","ADB permite operații de diagnosticare autorizate.")[p])
                }
                33->{
                    Text(tr("Memorie internă: 128 GB","Internal storage: 128 GB"),color=dark,fontWeight=FontWeight.Bold)
                    Diagram(svg[0],title,n){r->r.attr("v33ring","stroke-dasharray",(408.407*n/128).toString()+" 408.407");r.show("v33ring",n>0);r.txt("v33center",(24-n).toString()+" GB")}
                    val labels=if(en)listOf("System","Apps","Photos and videos","Other files","New recording","Free space")else listOf("Sistem","Aplicații","Fotografii și videoclipuri","Alte fișiere","Filmarea nouă","Spațiu liber")
                    val values=listOf(24,30,40,10,n,24-n);val colors=listOf(dark,green,graphic,Color(0xFF9CCB82),lime,Color(0xFFD1E6C5))
                    labels.forEachIndexed{i,t->Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically){Box(Modifier.size(12.dp).background(colors[i],RoundedCornerShape(3.dp)));Text(t,Modifier.weight(1f).padding(horizontal=8.dp),color=dark);Text(values[i].toString()+" GB",color=dark,fontWeight=FontWeight.Bold)}}
                    Range(tr("Dimensiunea filmării: ","Recording size: ")+n+" GB",n,0,24){n=it}
                    Bar(listOf(104/128f to dark,n/128f to graphic,(24-n)/128f to Color(0xFFD1E6C5)),30)
                    Result(tr("Ocupat inițial: 104 GB · Filmare: ","Initially used: 104 GB · Recording: ")+n+" GB · "+tr("Liber: ","Free: ")+(24-n)+" GB")
                }
                34->{
                    val t=n/100.0*10+(1-n/100.0)*200
                    Text(tr("100 de cereri de informații","100 information requests"),color=dark)
                    Diagram(svg[0],title,n){r->r.byClass("v34cell").forEachIndexed{i,e->e.setAttribute("fill",if(i<n)"#087C26" else "#D9A46C")}}
                    Result(tr("Găsite în cache: ","Cache hits: ")+n+" · "+tr("Necesită o nouă accesare: ","Require a new access: ")+(100-n))
                    Range(tr("Cereri găsite în cache: ","Cache hit rate: ")+n+"%",n,0,100){n=it}
                    Text(tr("Timp mediu fără cache: 200 ms","Average time without cache: 200 ms"),color=dark);Bar(listOf(1f to Color(0xFFD9A46C)))
                    Text(tr("Timp mediu cu cache","Average time with cache"),color=dark);Bar(listOf((t/200).toFloat() to green),25)
                    Result(tr("Timp mediu: ","Average time: ")+fmt.format(t)+" ms · "+tr("Fără cache: 200 ms","Without cache: 200 ms")+"\n"+tr("Timp economisit: ","Time saved: ")+fmt.format(200-t)+" ms · "+tr("Reducere: ","Reduction: ")+fmt.format((200-t)/2)+"%")
                }
                35->{
                    Diagram(svg[0],title,listOf(a,p)){r->r.show("v35contents",a);r.show("v35flaps",a);r.attr("v35lid","fill",if(a)"#064D2B" else "#B5F52C");r.show("v35tape",!a);r.byId("v35contents")?.nodes()?.filter{it.tagName=="rect"}?.forEachIndexed{i,e->e.setAttribute("fill",if(i==p)"#B5F52C" else "#E7F8DB")}}
                    Button(onClick={a=!a},modifier=Modifier.fillMaxWidth().heightIn(min=48.dp)){Text(if(a)tr("Închide pachetul","Close package")else tr("Deschide pachetul","Open package"))}
                    Text(if(a)tr("Explorează componentele pachetului.","Explore package components.")else tr("Pachet de instalare Android.","Android installation package."),color=dark)
                    if(a){Choices(tr("Explorează conținutul","Explore contents"),if(en)listOf("Code","Images","Configuration","Libraries")else listOf("Cod","Imagini","Configurare","Biblioteci"),p){p=it}
                    Result(if(en)listOf("Instructions that allow the app to function.","Icons, images and other visual resources.","Information about app identity, components and requested permissions.","Additional code components, possibly adapted to the phone processor.")[p]else listOf("Instrucțiunile care permit aplicației să funcționeze.","Pictograme, imagini și alte resurse vizuale ale aplicației.","Informații despre identitatea aplicației, componente și permisiunile solicitate.","Componente de cod suplimentare, care pot fi adaptate procesorului telefonului.")[p])}
                }
                36->{
                    Diagram(svg[0],title,n){r->r.byId("v36ticks")?.let{g->g.clear();repeat(n){i->g.rect(12+i*296f/n,108f,2f,17f,"#087C26")}}}
                    Range(tr("Sincronizări pe oră: ","Syncs per hour: ")+n,n,0,12){n=it}
                    Result(n.toString()+tr(" sincronizări · "," syncs · ")+(n*5)+tr(" secunde active"," active seconds"))
                }
                37->{
                    Diagram(svg[0],title)
                    Choices(tr("Explorează zona","Explore area"),if(en)listOf("System","Data")else listOf("Sistem","Date"),p){p=it}
                    Result(if(p==0)tr("Conține componente incluse în imaginea sistemului.","Contains components included in the system image.")else tr("Conține aplicații instalate și poate conține actualizări ale aplicațiilor de sistem.","Contains installed apps and may contain system app updates."))
                }
                else->Diagram(svg[0],title)
            }
            Text(tr(s.roNote,s.enNote),color=dark,style=MaterialTheme.typography.bodySmall)
            Text(tr("Exemplu informativ","Illustrative example"),color=dark,style=MaterialTheme.typography.labelMedium)
            if(s.id !in listOf(10,28,30,31,32)) OutlinedButton(onClick={n=n0;p=p0;p2=0;a=s.id==11;b=false},modifier=Modifier.fillMaxWidth().heightIn(min=48.dp)){Text(tr("Revino la exemplul inițial","Reset example"),color=dark)}
        }
    }
}
